static void _vby1_gfx_4kARGB8888_60HZ(void)
{
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_1PTO2P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_2PTO4P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_4PTO8P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_ARGB_MODE);

	//mft mode
	W2BYTEMSK(REG_0004_MODOSD1, 0x1, REG_0004_MODOSD1_REG_MFT_MODE);
	W2BYTEMSK(REG_0004_MODOSD1, 0x0, REG_0004_MODOSD1_REG_DIV_PIX_MODE);
	W2BYTEMSK(REG_0040_MODOSD1, 0xF00, REG_0040_MODOSD1_REG_HSIZE);
	W2BYTEMSK(REG_0044_MODOSD1, 0xF00, REG_0044_MODOSD1_REG_DIV_LEN);
	W2BYTEMSK(REG_0048_MODOSD1, 0x0, REG_0048_MODOSD1_REG_BASE0_ADDR);

	// mode 0 /mode 1 switch case usage?
	// W2BYTEMSK(REG_0008_MODOSD2, 0x2, REG_0008_MODOSD2_REG_FORMAT_MAP);

	W2BYTEMSK(REG_0188_MODOSD2, 0x2, REG_0188_MODOSD2_REG_VBY1_BYTE_MODE);
	W2BYTEMSK(REG_015C_MODD1, 0x1, REG_015C_MODD1_REG_SERI_FORMAT_OSD);
	W2BYTEMSK(REG_0144_MODD1, 0x1, REG_0144_MODD1_REG_SERI_OSD_MODE);
	//bit 2
	W2BYTEMSK(REG_0038_MODA1, 0x0, Fld(1,2,AC_MSKB0));
	W2BYTEMSK(REG_003C_MODOSD1, 0x22, REG_003C_MODOSD1_REG_MFT_READ_HDE_ST);
}

static void _vby1_gfx_4kARGB8101010_60HZ(void)
{
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_1PTO2P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_2PTO4P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_4PTO8P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_ARGB_MODE);

	//mft mode
	W2BYTEMSK(REG_0004_MODOSD1, 0x1, REG_0004_MODOSD1_REG_MFT_MODE);
	W2BYTEMSK(REG_0004_MODOSD1, 0x0, REG_0004_MODOSD1_REG_DIV_PIX_MODE);
	W2BYTEMSK(REG_0040_MODOSD1, 0xF00, REG_0040_MODOSD1_REG_HSIZE);
	W2BYTEMSK(REG_0044_MODOSD1, 0xF00, REG_0044_MODOSD1_REG_DIV_LEN);
	W2BYTEMSK(REG_0048_MODOSD1, 0x0, REG_0048_MODOSD1_REG_BASE0_ADDR);

	W2BYTEMSK(REG_0008_MODOSD2, 0x2, REG_0008_MODOSD2_REG_FORMAT_MAP);
	W2BYTEMSK(REG_0188_MODOSD2, 0x1, REG_0188_MODOSD2_REG_VBY1_BYTE_MODE);
	W2BYTEMSK(REG_015C_MODD1, 0x3, REG_015C_MODD1_REG_SERI_FORMAT_OSD);

	W2BYTEMSK(REG_0144_MODD1, 0x1, REG_0144_MODD1_REG_SERI_OSD_MODE);
	W2BYTEMSK(REG_0038_MODA1, 0x1, Fld(1,2,AC_MSKB0)); // bit2, 5byte mode
	W2BYTEMSK(REG_003C_MODOSD1, 0x22, REG_003C_MODOSD1_REG_MFT_READ_HDE_ST);
}

static void _vby1_gfx_4k_30HZ(void)
{
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_1PTO2P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_2PTO4P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_MOD_4PTO8P_EN);
	W2BYTEMSK(REG_0140_MODOSD1, 0x1, REG_0140_MODOSD1_REG_ARGB_MODE);

	//mft mode
	W2BYTEMSK(REG_0004_MODOSD1, 0x1, REG_0004_MODOSD1_REG_MFT_MODE);
	W2BYTEMSK(REG_0004_MODOSD1, 0x1, REG_0004_MODOSD1_REG_DIV_PIX_MODE);
	W2BYTEMSK(REG_0040_MODOSD1, 0xF00, REG_0040_MODOSD1_REG_HSIZE);
	W2BYTEMSK(REG_0044_MODOSD1, 0xF00, REG_0044_MODOSD1_REG_DIV_LEN);
	W2BYTEMSK(REG_0048_MODOSD1, 0x0, REG_0048_MODOSD1_REG_BASE0_ADDR);

	W2BYTEMSK(REG_0008_MODOSD2, 0x2, REG_0008_MODOSD2_REG_FORMAT_MAP);
	W2BYTEMSK(REG_0188_MODOSD2, 0x2, REG_0188_MODOSD2_REG_VBY1_BYTE_MODE);
	W2BYTEMSK(REG_015C_MODD1, 0x1, REG_015C_MODD1_REG_SERI_FORMAT_OSD);
	W2BYTEMSK(REG_0144_MODD1, 0x1, REG_0144_MODD1_REG_SERI_OSD_MODE);
	W2BYTEMSK(REG_0038_MODA1, 0x0, Fld(1,2,AC_MSKB0)); // bit2
	W2BYTEMSK(REG_003C_MODOSD1, 0x22, REG_003C_MODOSD1_REG_MFT_READ_HDE_ST);

}

static void _vby1_extv_4k_60HZ(void)
{
	W2BYTEMSK(REG_0000_MODD1, 0x0, REG_0000_MODD1_REG_V2_SEL);
	W2BYTEMSK(REG_0140_MODV21, 0x1, REG_0140_MODV21_REG_MOD_1PTO2P_EN);
	W2BYTEMSK(REG_0140_MODV21, 0x1, REG_0140_MODV21_REG_MOD_2PTO4P_EN);
	W2BYTEMSK(REG_0140_MODV21, 0x1, REG_0140_MODV21_REG_MOD_4PTO8P_EN);
	W2BYTEMSK(REG_0004_MODV22, 0x0, REG_0004_MODV22_REG_VBY1_8PTO16P_EN);
	W2BYTEMSK(REG_0008_MODV22, 0x0, REG_0008_MODV22_REG_FORMAT_MAP);
	W2BYTEMSK(REG_0188_MODV22, 0x2, REG_0188_MODV22_REG_VBY1_BYTE_MODE);
	W2BYTEMSK(REG_015C_MODD1, 0x1, REG_015C_MODD1_REG_SERI_FORMAT_V2);
	W2BYTEMSK(REG_0144_MODD1, 0x1, REG_0144_MODD1_REG_SERI_V2_MODE);
	//bit[1:1]
	W2BYTEMSK(REG_0038_MODA1, 0x0, Fld(1,1,AC_MSKB0));
	W2BYTEMSK(REG_003C_MODV21, 0x22, REG_003C_MODV21_REG_MFT_READ_HDE_ST);
}

static void _vby1_extv_4k_120HZ(void)
{
	W2BYTEMSK(REG_0000_MODD1, 0x1, REG_0000_MODD1_REG_V2_SEL);
	W2BYTEMSK(REG_0140_MODV21, 0x0, REG_0140_MODV21_REG_MOD_1PTO2P_EN);
	W2BYTEMSK(REG_0140_MODV21, 0x0, REG_0140_MODV21_REG_MOD_2PTO4P_EN);
	W2BYTEMSK(REG_0140_MODV21, 0x1, REG_0140_MODV21_REG_MOD_4PTO8P_EN);
	W2BYTEMSK(REG_0004_MODV22, 0x1, REG_0004_MODV22_REG_VBY1_8PTO16P_EN);
	W2BYTEMSK(REG_0008_MODV22, 0x0, REG_0008_MODV22_REG_FORMAT_MAP);
	W2BYTEMSK(REG_0188_MODV22, 0x2, REG_0188_MODV22_REG_VBY1_BYTE_MODE);
	W2BYTEMSK(REG_015C_MODD1, 0x1, REG_015C_MODD1_REG_SERI_FORMAT_V2);
	W2BYTEMSK(REG_0144_MODD1, 0x1, REG_0144_MODD1_REG_SERI_V2_MODE);
	//bit[1:1]
	W2BYTEMSK(REG_0038_MODA1, 0x0, Fld(1,1,AC_MSKB0));
	W2BYTEMSK(REG_003C_MODV21, 0x10, REG_003C_MODV21_REG_MFT_READ_HDE_ST);
}

static void _lvds_v_fhd_60HZ(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);

	if (priv == NULL) {
		printf("[%s] get device private fail\n", __func__);
		return;
	}

	// LVDS always 2p
	if (priv->pnl_lib_version != BOOT_PNL_VERSION0400 &&
		priv->pnl_lib_version != BOOT_PNL_VERSION0500) {
		if (priv->pnl_lib_version == BOOT_PNL_VERSION0200 ||
			priv->pnl_lib_version == BOOT_PNL_VERSION0203) {
			W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_1PTO2P_EN);
			W2BYTEMSK(REG_0140_MODV11, 0x1, REG_0140_MODV11_REG_MOD_2PTO4P_EN);
			W2BYTEMSK(REG_0140_MODV11, 0x1, REG_0140_MODV11_REG_MOD_4PTO8P_EN);
		} else {
			W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_2PTO4P_EN);
			if (priv->pnl_lib_version == BOOT_PNL_VERSION0300)
				W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_4PTO8P_EN);
			else
				W2BYTEMSK(REG_0140_MODV11, 0x1, REG_0140_MODV11_REG_MOD_4PTO8P_EN);
		}
	}
	W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_YUV_422_MODE);
	W2BYTEMSK(REG_0004_MODV11, 0x2, REG_0004_MODV11_REG_DIV_PIX_MODE);
	//W2BYTEMSK(REG_0040_MODV11, 0x780, REG_0040_MODV11_REG_HSIZE); // move into _vby1_set_mft()
	W2BYTEMSK(REG_0004_MODV12, 0x0, REG_0004_MODV12_REG_VBY1_8PTO16P_EN);
	W2BYTEMSK(REG_0004_MODV12, 0x0, REG_0004_MODV12_REG_VBY1_16PTO32P_EN);
	W2BYTEMSK(REG_0004_MODV12, 0x1, REG_0004_MODV12_REG_VBY1_HS_INV);
	W2BYTEMSK(REG_0004_MODV12, 0x1, REG_0004_MODV12_REG_VBY1_VS_INV);
	W2BYTEMSK(REG_0008_MODV12, 0x0, REG_0008_MODV12_REG_FORMAT_MAP);
	W2BYTEMSK(REG_015C_MODD1, 0x0, REG_015C_MODD1_REG_SERI_FORMAT_V1);
	//REG_0038_MODA1_REG_GCR_BANK_CLK_SRC_SEL bit[0:0]
	W2BYTEMSK(REG_0038_MODA1, 0x0, Fld(1,0,AC_MSKB0));
	W2BYTEMSK(REG_003C_MODV11, 0x10, REG_003C_MODV11_REG_MFT_READ_HDE_ST);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_RSCLK_TESTMD);
	W2BYTEMSK(REG_00E0_MODD1, priv->lvds_info.panel_lvds_ti_mode, REG_00E0_MODD1_REG_LVDS_TI);
	W2BYTEMSK(REG_00E0_MODD1, priv->lvds_info.panel_pdp_10bit, REG_00E0_MODD1_REG_PDP_10BIT);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_LVDS_PLASMA);
	W2BYTEMSK(REG_00E0_MODD1, (priv->lvds_info.panel_swap_lvds_pol), REG_00E0_MODD1_REG_CH_POLARITY);
	W2BYTEMSK(REG_00E0_MODD1, priv->lvds_info.panel_swap_lvds_ch, REG_00E0_MODD1_REG_PA_SWAP);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_PDP_CH4_SET);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_PDP_CH4_EN);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_PDP_CH3_SET);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_PDP_CH3_EN);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_PDP_MASK_SET);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_PDP_MASK_EN);
	W2BYTEMSK(REG_00E0_MODD1, priv->lvds_info.ti_bit_mode, REG_00E0_MODD1_REG_TI_BITMODE);
	W2BYTEMSK(REG_00E0_MODD1, 0x0, REG_00E0_MODD1_REG_LVDS_TESTERMD);
}

static void _vby1_v_fhd_60HZ(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);

	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}

	if (priv->pnl_lib_version != BOOT_PNL_VERSION0400 &&
		priv->pnl_lib_version != BOOT_PNL_VERSION0500 &&
		priv->pnl_lib_version != BOOT_PNL_VERSION0600) {
		if (priv->pnl_lib_version == BOOT_PNL_VERSION0200 ||
			priv->pnl_lib_version == BOOT_PNL_VERSION0203)
			W2BYTEMSK(REG_0140_MODV11, 0x1, REG_0140_MODV11_REG_MOD_2PTO4P_EN);
		else
			W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_2PTO4P_EN);
	}

	if (priv->pnl_lib_version == BOOT_PNL_VERSION0300)
		W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_4PTO8P_EN);
	else
		W2BYTEMSK(REG_0140_MODV11, 0x1, REG_0140_MODV11_REG_MOD_4PTO8P_EN);
	W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_YUV_422_MODE);
	W2BYTEMSK(REG_0004_MODV11, 0x2, REG_0004_MODV11_REG_DIV_PIX_MODE);
	//W2BYTEMSK(REG_0040_MODV11, 0x780, REG_0040_MODV11_REG_HSIZE); // move into _vby1_set_mft()
	W2BYTEMSK(REG_0004_MODV12, 0x0, REG_0004_MODV12_REG_VBY1_8PTO16P_EN);
	W2BYTEMSK(REG_0004_MODV12, 0x0, REG_0004_MODV12_REG_VBY1_16PTO32P_EN);
	W2BYTEMSK(REG_0004_MODV12, 0x1, REG_0004_MODV12_REG_VBY1_HS_INV);
	W2BYTEMSK(REG_0004_MODV12, 0x1, REG_0004_MODV12_REG_VBY1_VS_INV);
	W2BYTEMSK(REG_0008_MODV12, 0x0, REG_0008_MODV12_REG_FORMAT_MAP);

	if (priv->pnl_lib_version == BOOT_PNL_VERSION0200 ||
		priv->pnl_lib_version == BOOT_PNL_VERSION0203 ||
		priv->pnl_lib_version == BOOT_PNL_VERSION0400 ||
		priv->pnl_lib_version == BOOT_PNL_VERSION0500 ||
		priv->pnl_lib_version == BOOT_PNL_VERSION0600)
		W2BYTEMSK(REG_003C_MODV11, 0x6, REG_003C_MODV11_REG_MFT_READ_HDE_ST);
	else
		W2BYTEMSK(REG_003C_MODV11, 0x10, REG_003C_MODV11_REG_MFT_READ_HDE_ST);
}

