static void _default_free_swap(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);

	if (priv == NULL) {
		printf("[%s] get device private fail\n", __func__);
		return;
	}

	if (priv->linktype != E_LINK_VB1) {
		printf("[%s] only support E_LINK_VB1\n", __func__);
		return;
	}

	switch (priv->lane_info.ctrl_lanes) {
	case VBO_USE_LANE_NUM_64:
		_vby1_64lane_def_free_swap(dev);
		break;
	case VBO_USE_LANE_NUM_40:
		_vby1_40lane_def_free_swap(dev);
		break;
	case VBO_USE_LANE_NUM_32:
		_vby1_32lane_def_free_swap(dev);
		break;
	case VBO_USE_LANE_NUM_16:
		_vby1_16lane_def_free_swap(dev);
		break;
	case VBO_USE_LANE_NUM_8:
		_vby1_8lane_def_free_swap(dev);
		break;
	default:
		_vby1_32lane_def_free_swap(dev);
		break;
	}
}

