static void _vby1_set_byte_mode(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);
	en_vbo_bytemode vbo_byte = E_VBO_NO_LINK;

	if (priv == NULL) {
		printf("[%s] get device private fail\n", __func__);
		return;
	}

	if (priv->linktype != E_LINK_VB1)
		return;

	vbo_byte = priv->vbo_byte;

	if (priv->pnl_lib_version == BOOT_PNL_VERSION0200 ||
			priv->pnl_lib_version == BOOT_PNL_VERSION0203 ||
			priv->pnl_lib_version == BOOT_PNL_VERSION0300 ||
			priv->pnl_lib_version == BOOT_PNL_VERSION0400 ||
			priv->pnl_lib_version == BOOT_PNL_VERSION0500 ||
			priv->pnl_lib_version == BOOT_PNL_VERSION0600) {
		if (vbo_byte == E_VBO_5BYTE_MODE) {
			// 5 byte mode
			W2BYTEMSK(REG_0188_MODV12, 1, REG_0188_MODV12_REG_VBY1_BYTE_MODE);
			W2BYTEMSK(REG_015C_MODD1, 0x3, REG_015C_MODD1_REG_SERI_FORMAT_V1);
			W2BYTEMSK(REG_0038_MODA1, 0x1, Fld(1,0,AC_MSKB0));
		} else {
			// 4 byte mode
			W2BYTEMSK(REG_0188_MODV12, 2, REG_0188_MODV12_REG_VBY1_BYTE_MODE);
			W2BYTEMSK(REG_015C_MODD1, 0x1, REG_015C_MODD1_REG_SERI_FORMAT_V1);
			W2BYTEMSK(REG_0038_MODA1, 0x0, Fld(1,0,AC_MSKB0));
		}
	} else {
		if (priv->out_timing == E_8K4K_60HZ &&
				priv->out_format == E_OUTPUT_YUV422) {
			// 5 byte mode
			W2BYTEMSK(REG_0188_MODV12, 1, REG_0188_MODV12_REG_VBY1_BYTE_MODE);
			W2BYTEMSK(REG_015C_MODD1, 0x3, REG_015C_MODD1_REG_SERI_FORMAT_V1);
			W2BYTEMSK(REG_0038_MODA1, 0x1, Fld(1,0,AC_MSKB0));
		} else {
			// 4 byte mode
			W2BYTEMSK(REG_0188_MODV12, 2, REG_0188_MODV12_REG_VBY1_BYTE_MODE);
			W2BYTEMSK(REG_015C_MODD1, 0x1, REG_015C_MODD1_REG_SERI_FORMAT_V1);
			W2BYTEMSK(REG_0038_MODA1, 0x0, Fld(1,0,AC_MSKB0));
		}
	}
}

void vby1_set_pn_swap(u32 pnl_lib_version)
{
	if (pnl_lib_version == BOOT_PNL_VERSION0100) {
		//Currently, rcon value should read from efuse, and can not be modified by customer.
		//For ES1 PN Swap.
		W2BYTEMSK(REG_00E0_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch0
		W2BYTEMSK(REG_00E0_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch1
		W2BYTEMSK(REG_00E4_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch2
		W2BYTEMSK(REG_00E4_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch3
		W2BYTEMSK(REG_00E8_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch4
		W2BYTEMSK(REG_00E8_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch5
		W2BYTEMSK(REG_00EC_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch6
		W2BYTEMSK(REG_00EC_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch7
		W2BYTEMSK(REG_00F0_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch8
		W2BYTEMSK(REG_00F0_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch9
		W2BYTEMSK(REG_00F4_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch10
		W2BYTEMSK(REG_00F4_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch11
		W2BYTEMSK(REG_00F8_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch12
		W2BYTEMSK(REG_00F8_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch13
		W2BYTEMSK(REG_00FC_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch14
		W2BYTEMSK(REG_00FC_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch15
		W2BYTEMSK(REG_0100_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch16
		W2BYTEMSK(REG_0100_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch17
		W2BYTEMSK(REG_0104_MODA1, 0x1, Fld(1,5,AC_MSKB0));//ch18
		W2BYTEMSK(REG_0104_MODA1, 0x1, Fld(1,13,AC_MSKB1));//ch19
		W2BYTEMSK(REG_00E0_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch20
		W2BYTEMSK(REG_00E0_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch21
		W2BYTEMSK(REG_00E4_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch22
		W2BYTEMSK(REG_00E4_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch23
		W2BYTEMSK(REG_00E8_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch24
		W2BYTEMSK(REG_00E8_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch25
		W2BYTEMSK(REG_00EC_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch26
		W2BYTEMSK(REG_00EC_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch27
		W2BYTEMSK(REG_00F0_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch28
		W2BYTEMSK(REG_00F0_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch29
		W2BYTEMSK(REG_00F4_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch30
		W2BYTEMSK(REG_00F4_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch31
		W2BYTEMSK(REG_00F8_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch32
		W2BYTEMSK(REG_00F8_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch33
		W2BYTEMSK(REG_00FC_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch34
		W2BYTEMSK(REG_00FC_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch35
		W2BYTEMSK(REG_0100_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch36
		W2BYTEMSK(REG_0100_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch37
		W2BYTEMSK(REG_0104_MODA2, 0x1, Fld(1,5,AC_MSKB0));//ch38
		W2BYTEMSK(REG_0104_MODA2, 0x1, Fld(1,13,AC_MSKB1));//ch39
	} else if (pnl_lib_version >= BOOT_PNL_VERSION0200) {
		if ((pnl_lib_version == BOOT_PNL_VERSION0200) ||
			(pnl_lib_version == BOOT_PNL_VERSION0203) ||
			(pnl_lib_version == BOOT_PNL_VERSION0300)) {
			W2BYTEMSK(REG_0008_MODA1, REG_ALL, REG_0008_MODA1_REG_GCR_DS_POL_CH_19_00_0);
			W2BYTEMSK(REG_000C_MODA1, REG_ALL, REG_000C_MODA1_REG_GCR_DS_POL_CH_19_00_1);
			W2BYTEMSK(REG_0008_MODA2, REG_ALL, REG_0008_MODA2_REG_GCR_DS_POL_CH_39_20_0);
			W2BYTEMSK(REG_000C_MODA2, REG_ALL, REG_000C_MODA2_REG_GCR_DS_POL_CH_39_20_1);
			if (pnl_lib_version == BOOT_PNL_VERSION0300) {
				W2BYTEMSK(REG_0008_MODA3, REG_ALL, REG_0008_MODA3_REG_GCR_DS_POL_CH_59_40_0);
				W2BYTEMSK(REG_000C_MODA3, REG_ALL, REG_000C_MODA3_REG_GCR_DS_POL_CH_59_40_1);
				W2BYTEMSK(REG_0008_MODA4, REG_ALL, REG_0008_MODA4_REG_GCR_DS_POL_CH_63_60);
			}
		}

		if (pnl_lib_version == BOOT_PNL_VERSION0400 ||
			pnl_lib_version == BOOT_PNL_VERSION0500 ||
			pnl_lib_version == BOOT_PNL_VERSION0600)
			W2BYTEMSK(REG_0008_MODA1, 0xFFF, REG_0008_MODA1_REG_GCR_DS_POL_CH_19_00_0);
	}
}

static void _vby1_set_SCTCON_MISC(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);
	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}

	if (priv->out_format == E_OUTPUT_YUV444) {
		W2BYTEMSK(REG_0004_SCTCON_MISC_BKA3E0, 0, REG_0004_SCTCON_MISC_BKA3E0_REG_SCTCON_MISC_BYPASS_ALL);
		W2BYTEMSK(REG_0040_SCTCON_MISC_BKA3E0, 1, REG_0040_SCTCON_MISC_BKA3E0_REG_444TO422_BYPASS);
		W2BYTEMSK(REG_0040_SCTCON_MISC_BKA3E0, 0, REG_0040_SCTCON_MISC_BKA3E0_REG_MOD_REORDER );
	} else if (priv->out_format == E_OUTPUT_YUV422) {
		W2BYTEMSK(REG_0004_SCTCON_MISC_BKA3E0, 0, REG_0004_SCTCON_MISC_BKA3E0_REG_SCTCON_MISC_BYPASS_ALL); //csc out bypass
		W2BYTEMSK(REG_0040_SCTCON_MISC_BKA3E0, 0, REG_0040_SCTCON_MISC_BKA3E0_REG_444TO422_BYPASS);
		W2BYTEMSK(REG_0040_SCTCON_MISC_BKA3E0, 1, REG_0040_SCTCON_MISC_BKA3E0_REG_MOD_REORDER );
	} else {
		W2BYTEMSK(REG_0004_SCTCON_MISC_BKA3E0, 1, REG_0004_SCTCON_MISC_BKA3E0_REG_SCTCON_MISC_BYPASS_ALL); //csc out bypass
	}
}


static void _vby1_set_mft(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);
	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}

	u8 htt_slot = 0;

	if(priv->out_format == E_OUTPUT_YUV422)
		W2BYTEMSK(REG_0040_MODV11, priv->de_width/2, REG_0040_MODV11_REG_HSIZE);
	else
		W2BYTEMSK(REG_0040_MODV11, priv->de_width, REG_0040_MODV11_REG_HSIZE);

	if (priv->linktype == E_LINK_VB1) {
		switch(priv->div_sec) {
		case 1:
			W2BYTEMSK(REG_0004_MODV11, 0x1, REG_0004_MODV11_REG_MFT_MODE);
			if (priv->out_format == E_OUTPUT_YUV422)
				W2BYTEMSK(REG_0044_MODV11, priv->de_width/2, REG_0044_MODV11_REG_DIV_LEN);
			else
				W2BYTEMSK(REG_0044_MODV11, priv->de_width, REG_0044_MODV11_REG_DIV_LEN);

			W2BYTEMSK(REG_0048_MODV11, 0x0, REG_0048_MODV11_REG_BASE0_ADDR);
		break;

		case 2:
			W2BYTEMSK(REG_0004_MODV11, 0x2, REG_0004_MODV11_REG_MFT_MODE);
			if (priv->out_format == E_OUTPUT_YUV422)
				W2BYTEMSK(REG_0044_MODV11, priv->de_width/4, REG_0044_MODV11_REG_DIV_LEN);
			else
				W2BYTEMSK(REG_0044_MODV11, priv->de_width/2, REG_0044_MODV11_REG_DIV_LEN);

			W2BYTEMSK(REG_0048_MODV11, 0x0, REG_0048_MODV11_REG_BASE0_ADDR);
			W2BYTEMSK(REG_004C_MODV11, priv->de_width/2, REG_004C_MODV11_REG_BASE1_ADDR);
		break;

		case 4:
			W2BYTEMSK(REG_0004_MODV11, 0x3, REG_0004_MODV11_REG_MFT_MODE);
			W2BYTEMSK(REG_0044_MODV11, priv->de_width/4, REG_0044_MODV11_REG_DIV_LEN);
			W2BYTEMSK(REG_0048_MODV11, 0x0, REG_0048_MODV11_REG_BASE0_ADDR);
			W2BYTEMSK(REG_004C_MODV11, priv->de_width/4, REG_004C_MODV11_REG_BASE1_ADDR);
			W2BYTEMSK(REG_0050_MODV11, priv->de_width/2, REG_0050_MODV11_REG_BASE2_ADDR);
			W2BYTEMSK(REG_0054_MODV11, priv->de_width*3/4, REG_0054_MODV11_REG_BASE3_ADDR);
		break;

		case 8:
			W2BYTEMSK(REG_0004_MODV11, 0x4, REG_0004_MODV11_REG_MFT_MODE);
			W2BYTEMSK(REG_0044_MODV11, priv->de_width/8, REG_0044_MODV11_REG_DIV_LEN);
			W2BYTEMSK(REG_0048_MODV11, 0x0, REG_0048_MODV11_REG_BASE0_ADDR);
			W2BYTEMSK(REG_004C_MODV11, priv->de_width/8, REG_004C_MODV11_REG_BASE1_ADDR);
			W2BYTEMSK(REG_0050_MODV11, priv->de_width/4, REG_0050_MODV11_REG_BASE2_ADDR);
			W2BYTEMSK(REG_0054_MODV11, priv->de_width*3/8, REG_0054_MODV11_REG_BASE3_ADDR);
			W2BYTEMSK(REG_0058_MODV11, priv->de_width/2, REG_0058_MODV11_REG_BASE4_ADDR);
			W2BYTEMSK(REG_005C_MODV11, priv->de_width*5/8, REG_005C_MODV11_REG_BASE5_ADDR);
			W2BYTEMSK(REG_0060_MODV11, priv->de_width*6/8, REG_0060_MODV11_REG_BASE6_ADDR);
			W2BYTEMSK(REG_0064_MODV11, priv->de_width*7/8, REG_0064_MODV11_REG_BASE7_ADDR);
		break;

		default:
			debug("UNSUPPORT MFT Division\n");
		break;

		}

		if (priv->lanes/MFT_P > 0)
			htt_slot = priv->lanes/MFT_P -1;
		else
			htt_slot = 0;

		W2BYTEMSK(REG_000C_MODV11, htt_slot, REG_000C_MODV11_REG_MFT_VLD_WRAP_FIX_HTT);
	}

	if (priv->linktype == E_LINK_LVDS) {
		//prepare for h mirror case
		W2BYTEMSK(REG_0004_MODV11, 0x1, REG_0004_MODV11_REG_MFT_MODE);
		W2BYTEMSK(REG_0044_MODV11, 0x780, REG_0044_MODV11_REG_DIV_LEN);
		W2BYTEMSK(REG_0048_MODV11, 0x0, REG_0048_MODV11_REG_BASE0_ADDR);
	}
#ifdef CONFIG_HAPS
	//if (priv->pnl_lib_version == BOOT_PNL_VERSION0500)
	{
		// HAPS case, bypass MFT
		W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_1PTO2P_EN);
		W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_2PTO4P_EN);
		W2BYTEMSK(REG_0140_MODV11, 0x0, REG_0140_MODV11_REG_MOD_4PTO8P_EN);
		W2BYTEMSK(REG_0004_MODV11, 0x0, REG_0004_MODV11_REG_DIV_PIX_MODE);
		W2BYTEMSK(REG_0004_MODV11, 0x0, REG_0004_MODV11_REG_MFT_MODE);
	}
#endif  //#ifdef CONFIG
}

static void _vby1_extv_set_mft(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);

	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}
	u8 htt_slot = 0;

	if (IS_VB1_OUT(priv->linktype)) {

		if (priv->div_sec == 1) {
			W2BYTEMSK(REG_0004_MODV21, 0x1, REG_0004_MODV21_REG_MFT_MODE);
			W2BYTEMSK(REG_0004_MODV21, 0x0, REG_0004_MODV21_REG_DIV_PIX_MODE);
			W2BYTEMSK(REG_0040_MODV21, priv->de_width, REG_0040_MODV21_REG_HSIZE);
			W2BYTEMSK(REG_0044_MODV21, priv->de_width, REG_0044_MODV21_REG_DIV_LEN);
			W2BYTEMSK(REG_0048_MODV21, 0x0, REG_0048_MODV21_REG_BASE0_ADDR);
		} else if (priv->div_sec == 2) {
			W2BYTEMSK(REG_0004_MODV21, 0x2, REG_0004_MODV21_REG_MFT_MODE);
			W2BYTEMSK(REG_0004_MODV21, 0x0, REG_0004_MODV21_REG_DIV_PIX_MODE);
			W2BYTEMSK(REG_0040_MODV21, priv->de_width, REG_0040_MODV21_REG_HSIZE);
			W2BYTEMSK(REG_0044_MODV21, priv->de_width/2, REG_0044_MODV21_REG_DIV_LEN);
			W2BYTEMSK(REG_0048_MODV21, 0x0, REG_0048_MODV21_REG_BASE0_ADDR);
			W2BYTEMSK(REG_004C_MODV21, priv->de_width/2, REG_004C_MODV21_REG_BASE1_ADDR);
		} else if (priv->div_sec == 4) {
			W2BYTEMSK(REG_0004_MODV21, 0x3, REG_0004_MODV21_REG_MFT_MODE);
			W2BYTEMSK(REG_0044_MODV21, priv->de_width/4, REG_0044_MODV21_REG_DIV_LEN);
			W2BYTEMSK(REG_0048_MODV21, 0x0, REG_0048_MODV21_REG_BASE0_ADDR);
                        W2BYTEMSK(REG_004C_MODV21, priv->de_width/4, REG_004C_MODV21_REG_BASE1_ADDR);
			W2BYTEMSK(REG_0050_MODV21, priv->de_width/2, REG_0050_MODV21_REG_BASE2_ADDR);
			W2BYTEMSK(REG_0054_MODV21, priv->de_width*3/4, REG_0054_MODV21_REG_BASE3_ADDR);
		} else {
			debug("[%s] Unsupport MFT mode\n", __func__);
		}
	}

	if (priv->lanes/MFT_P > 0)
		htt_slot = priv->lanes/MFT_P -1;
	else
		htt_slot = 0;

	W2BYTEMSK(REG_000C_MODV21, htt_slot, REG_000C_MODV21_REG_MFT_VLD_WRAP_FIX_HTT);

}

