			W2BYTEMSK(REG_0064_MODA1, bOutputConfigEn[E_BOOT_PNL_OUTPUT_LANE9], REG_0064_MODA1_REG_OUTPUT_CONF_CH09);
			W2BYTEMSK(REG_0064_MODA1, bOutputConfigEn[E_BOOT_PNL_OUTPUT_LANE10], REG_0064_MODA1_REG_OUTPUT_CONF_CH10);
