				W2BYTEMSK(REG_0064_MODA1, bOutputConfigEn[E_BOOT_PNL_OUTPUT_LANE14], REG_0064_MODA1_REG_OUTPUT_CONF_CH14);
				W2BYTEMSK(REG_0064_MODA1, bOutputConfigEn[E_BOOT_PNL_OUTPUT_LANE15], REG_0064_MODA1_REG_OUTPUT_CONF_CH15);

				W2BYTEMSK(REG_0068_MODA1, bOutputConfigEn[E_BOOT_PNL_OUTPUT_LANE16], REG_0068_MODA1_REG_OUTPUT_CONF_CH16);
				W2BYTEMSK(REG_0068_MODA1, bOutputConfigEn[E_BOOT_PNL_OUTPUT_LANE17], REG_0068_MODA1_REG_OUTPUT_CONF_CH17);
