void mtk_extv_controlbit_init(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);
	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}

	//Mdata V2
	W2BYTEMSK(REG_0020_MODV22,0x0200,Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_0024_MODV22,0x0010,Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_0028_MODV22,0x0000,Fld(16,0,AC_FULLW10));

	//Lane 1 bit 0~bit 15 init value
	//bit[0:7]FNI=0, bit[8]VGSF=1,bit[12:14]FE SoC Type=001,bit[15]CBVF=0
	//24bit:0x001100
	W2BYTEMSK(REG_0040_MODV22,0x1100,Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_0044_MODV22,0x0000,Fld(16,0,AC_FULLW10));

}

void mtk_gfx_controlbit_init(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);
	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}

	//lane1~lan4
	//lane1:bit[0:12]HTT,bit[14]GF=1,bit[15]VF=1
	//lane2:bit[0:11]VTT
	//lane3:bit[0:8]VTT
	u16 line1Ctr = 0x0, line2Ctr = 0x0, line3Ctr = 0x0, line4Ctr = 0x0;
	u16 valid_flag=0x1, gf_flag= 0x1;
	priv->typ_htt = priv->typ_htt & 0x1FFF;
	line1Ctr = priv->typ_htt | (valid_flag<<15) | (gf_flag<<14);
	line2Ctr = priv->typ_vtt & 0xFFF;
	line3Ctr = priv->de_hstart & 0x1FF;
	line4Ctr = priv->de_vstart & 0x7F;

	//Mdata OSD
	W2BYTEMSK(REG_0020_MODOSD2,0x0200,Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_0024_MODOSD2,0x0010,Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_0028_MODOSD2,0x0000,Fld(16,0,AC_FULLW10));

	//lane1~lan3
	W2BYTEMSK(REG_0040_MODOSD2,line1Ctr & 0xffff,Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_0044_MODOSD2,(line2Ctr & 0xff),Fld(8,8,AC_MSKB1));
	W2BYTEMSK(REG_0048_MODOSD2,(line2Ctr>>8),Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_004C_MODOSD2,(line3Ctr & 0xffff),Fld(16,0,AC_FULLW10));
	W2BYTEMSK(REG_0050_MODOSD2,(line4Ctr & 0xff),Fld(8,8,AC_MSKB1));
	W2BYTEMSK(REG_0054_MODOSD2,(line4Ctr>>8),Fld(16,0,AC_FULLW10));

}

static void _mtk_dither_depth_setting(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);
	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}
	if(priv->dither_info.dither_capability == 0)//input 10bit case
		switch(priv->dither_info.dither_depth) {
		case E_DITHER_DEPTH_6:
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x1, REG_00FC_PAFRC_BKA324_REG_DITH_BITS);//dither 4 bit (10to6 case)
			break;
		case E_DITHER_DEPTH_8:
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_DITH_BITS);//dither 2 bit (10to8 case)
			break;
		case E_DITHER_DEPTH_10:
			//means by pass(10to10 case)
			priv->dither_info.dither_pattern = E_DITHER_BYPASS;
			break;
		case E_DITHER_DEPTH_12:
		default:
			// To avoid dither pattern works in not support case, force bypass mode
			priv->dither_info.dither_pattern = E_DITHER_BYPASS;
			debug("[%s] dither depth not support\n", __func__);
			break;
		}
	else if (priv->dither_info.dither_capability == 1) {//input 12bit case
		switch(priv->dither_info.dither_depth) {
		case E_DITHER_DEPTH_6:
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x1, REG_00FC_PAFRC_BKA324_REG_DITH_BITS);//dither 4 bit (12to6 case)
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_PAFRC_INPUT_IS_12B);
			break;
		case E_DITHER_DEPTH_8:
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x1, REG_00FC_PAFRC_BKA324_REG_DITH_BITS);//dither 4 bit (12to8 case)
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x1, REG_00FC_PAFRC_BKA324_REG_PAFRC_INPUT_IS_12B);
			break;
		case E_DITHER_DEPTH_10:
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_DITH_BITS);//dither 2 bit (12to10 case)
			W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x1, REG_00FC_PAFRC_BKA324_REG_PAFRC_INPUT_IS_12B);
			break;
		case E_DITHER_DEPTH_12:
			//means by pass(12to12 case)
			priv->dither_info.dither_pattern = E_DITHER_BYPASS;
			break;
		default:
			// To avoid dither pattern works in not support case, force bypass mode
			priv->dither_info.dither_pattern = E_DITHER_BYPASS;
			debug("[%s] dither depth not support\n", __func__);
			break;
		}

	}
	else
	{
		debug("[%s] dither capability not support\n", __func__);
	}

}

static void _mtk_dither_12bit_setting(struct udevice *dev)
{
	struct mtk_panel_priv *priv = dev_get_priv(dev);
	if (priv == NULL) {
		debug("[%s] get device private fail\n", __func__);
		return;
	}

	W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_BOOST_EN);
	W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_DITHER_BIT_1);
	W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_LSB_ALIGNMENT_SEL);

	if((priv->dither_info.dither_depth == E_DITHER_DEPTH_12)||(priv->dither_info.dither_pattern ==E_DITHER_BYPASS))
	{
		W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x1, REG_00FC_PAFRC_BKA324_REG_BYPASS_MODE);
	}
	else
	{
		W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_BYPASS_MODE);
	}

	W2BYTEMSK(REG_00FC_PAFRC_BKA324, 0x0, REG_00FC_PAFRC_BKA324_REG_PAFRC_INPUT_IS_13B);

	W2BYTEMSK(REG_012C_PAFRC_BKA324, 0x0, REG_012C_PAFRC_BKA324_REG_13B_CLAMP_MODE);

}

