typedef struct __attribute__((packed))
{
    u16 u16Version;               //[15:8]: major, [7:0]: minor version
    u8 u8LineOD_en;               //[0]: line od enable
    u8 u8SeparateFlag;            //[0]: channel separate flag [1]: table separate flag (unused)
    u32 u32YearMonthDayMinute;    //[31:25]: reserved, [24:20]: year, [19:16]: month, [15:11]: day, [10:0]: minute
    u8 u8TableMatrix;             //0: 19x19, 1: 17x17
    u8 u8RegionNumber;            //(Version>1 0: 1x1, 1: 2x8, 2:4X4) (Version<=1 16: 4x4 or 2x8, 1: 1x1)
    u8 u8GainMatrix;            //0: 4x4, 1: 13x9
    u8 u8GainRegion;            //0: 1x1
    u8 u8TableBit;                //(Version>2 0: 8bit 1:12bit) (Version<=2 no this member)
} ST_PNL_LINE_OD_SUB_HEADER, *pST_PNL_LINE_OD_SUB_HEADER;

