#define TCON_DEFAUL_PATH_LINUX            "config/tcon/TCON20.bin"
#define TCON_DEFAUL_PATH_AOSP             "bsp/common/TCON_BIN/TCON20.bin"

#define EVA_DEFAUL_PATH_MI                "tcon/EVA.bin"
#define EVA_DEFAUL_PATH_LINUX             "config/tcon/EVA.bin"
#define EVA_DEFAUL_PATH_AOSP              "bsp/common/TCON_BIN/EVA.bin"

#define PANELGAMMA_DEFAULT_PATH_MI        "gamma/panel_gamma.bin"
#define PANELGAMMA_DEFAULT_PATH_LINUX     "config/gamma/panel_gamma.bin"
#define PANELGAMMA_DEFAULT_PATH_AOSP      "bsp/common/GAMMA_BIN/panel_gamma.bin"
#define AUTO_PANEL_GAMMA_DATA_SIZE        (1024 * 2 * 3)  //1024 Entry, 2 Byte, RGB
#define PANEL_GAMMA_PRE_CHANNEL_LEN       (1024 * 2)
#define CSPI_GAMMA_SIZE_120HZ             (16)
#define USIT_GAMMA_SIZE_120HZ             (14)

static u16 _registerTypeToSize(u8 u8Registertype)
{
    E_PNL_TCON20_REGISTERTYPE en = (E_PNL_TCON20_REGISTERTYPE)u8Registertype;
    switch (en)
    {
        case EN_TCON20_REGISTERTYPE_6_BYTES:
            return TCON_REGISTERTYPE_6_BYTES;
        case EN_TCON20_REGISTERTYPE_4_BYTES:
            return TCON_REGISTERTYPE_4_BYTES;
        case EN_TCON20_REGISTERTYPE_POWERSEQENCE_9_BYTES:
            return TCON_REGISTERTYPE_POWERSEQENCE_9_BYTES;
        case EN_TCON20_REGISTERTYPE_POWERSEQENCE_7_BYTES:
            return TCON_REGISTERTYPE_POWERSEQENCE_7_BYTES;
        case EN_TCON20_REGISTERTYPE_POWERSEQENCE_WITHSUB_15_BYTES:
            return TCON_REGISTERTYPE_POWERSEQENCE_WITHSUB_15_BYTES;
        case EN_TCON20_REGISTERTYPE_POWERSEQENCE_WITHSUB_11_BYTES:
            return TCON_REGISTERTYPE_POWERSEQENCE_WITHSUB_11_BYTES;
        case EN_TCON20_REGISTERTYPE_PANEL_1_BYTES:
            return TCON_REGISTERTYPE_1_BYTES;
        case EN_TCON20_REGISTERTYPE_PANEL_6_BYTES:
        case EN_TCON20_REGISTERTYPE_PANEL_6_BYTES_NEWSSC:
            return TCON_REGISTERTYPE_6_BYTES;
        case EN_TCON20_REGISTERTYPE_POWERSEQUENCE_14BYTES:
            return TCON_REGISTERTYPE_POWERSEQENCE_WITHSUB_14_BYTES;
        default:
            debug("register type out of range: %d", en);
            return 0;
    }
}

//Panel Gamma
///halPNL.c
static void MHal_PNL_SetPanelGammaByPass(bool bEnable)
{
    W2BYTEMSK(REG_01B0_PAFRC_BKA324_V004,bEnable?0x1:0x0,REG_01B0_PAFRC_BKA324_V004_REG_GAMMA_BYPASS_01B0);
}
static bool MHal_PNL_GetPanelGammaByPass(void)
{
    return R2BYTEMSK(REG_01B0_PAFRC_BKA324_V004,REG_01B0_PAFRC_BKA324_V004_REG_GAMMA_BYPASS_01B0);
}

static void MHal_PNL_PanelGamma_Enable(bool bEnable)
{
    W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,bEnable?0x1:0x0,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_EN_01B4);
}
static bool MHal_PNL_GetPanelGamma_Enable(void)
{
    return R2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_EN_01B4);
}
static void MHal_PNL_PanelGamma_Set2LUTMode(struct udevice *dev,MS_PNL_PNLGAMMA_Config *pstPNLGammaConfig)
{
    struct mtk_panel_priv *priv = dev_get_priv(dev);

    if (priv == NULL) {
        debug("[%s] get device private fail\n", __func__);
        return;
    }
    if(priv->pnl_lib_version != VERSION4)
    {
        W2BYTEMSK(REG_01A8_PAFRC_BKA324,(pstPNLGammaConfig->u8Gamma2LutMode & 0x03),REG_01A8_PAFRC_BKA324_REG_GAMMA_2LUT_MODE_SEL);
        W2BYTEMSK(REG_01A4_PAFRC_BKA324,(pstPNLGammaConfig->bGamma2LutEnable? 0x1:0x0),REG_01A4_PAFRC_BKA324_REG_GAMMA_2LUT_EN);
    }
}
static bool MHal_PNL_PanelGamma_Get2LutEnable(struct udevice *dev)
{
    struct mtk_panel_priv *priv = dev_get_priv(dev);

    if (priv == NULL) {
        debug("[%s] get device private fail\n", __func__);
        return FALSE;
    }
    if(priv->pnl_lib_version != VERSION4)
    {
        return R2BYTEMSK(REG_01A4_PAFRC_BKA324,REG_01A4_PAFRC_BKA324_REG_GAMMA_2LUT_EN);
    }
    else
    {
        return FALSE;
    }
}

static bool MHal_PNL_Support_PanelGamma_W_Channel(void)
{
#ifdef SUPPORT_PANEL_GAMMA_W_CHANNEL
    return SUPPORT_PANEL_GAMMA_W_CHANNEL;
#endif
    return FALSE;
}

static bool MHal_PNL_GetPanelGammaTbl_From_Reg(struct udevice *dev, ST_PNL_PNLGAMMATBL *pstGetPNLGammaTbl)
{
    u16 u16NumOfLevel =1024;
    u16 u16Addr = 0;
    u8 u8Channel =0;
    bool bGammaByPass = MHal_PNL_GetPanelGammaByPass();
    bool bSupportWChannel = MHal_PNL_Support_PanelGamma_W_Channel();
    u16 u16Timeout = 0;
    struct mtk_panel_priv *priv = dev_get_priv(dev);

    if (priv == NULL) {
        debug("[%s] get device private fail\n", __func__);
        return FALSE;
    }

    CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16RChannel0);
    CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16GChannel0);
    CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16BChannel0);
    if(bSupportWChannel == TRUE)
    {
        CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16WChannel0);
    }

    if (bGammaByPass == TRUE)
    {
        MHal_PNL_SetPanelGammaByPass(FALSE);
    }

    for(u8Channel = 0; u8Channel <4; u8Channel++)
    {
        //1. set Read channel
        W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,u8Channel,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_CH_SEL_01B4);

        for(u16Addr = 0; u16Addr < u16NumOfLevel; u16Addr++)
        {
            //2. set LUT_ADDR 0
            W2BYTEMSK(REG_01B0_PAFRC_BKA324_V004,u16Addr,REG_01B0_PAFRC_BKA324_V004_REG_GAMMA_ADR_01B0);
            //3. toggle LUT_R_FLAG
            W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,1,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_RD_EN_01B4);
            while(R2BYTEMSK(REG_01B4_PAFRC_BKA324_V004, REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_RD_EN_01B4) && (u16Timeout < MAX_DELAY_TIME))
            {
                udelay(10);
                u16Timeout++;
            }

            if(u8Channel == 0) //R channel
            {
                pstGetPNLGammaTbl->pu16RChannel0[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
            }
            if(u8Channel == 1) //G channel
            {
                pstGetPNLGammaTbl->pu16GChannel0[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
            }
            if(u8Channel == 2) //B channel
            {
                pstGetPNLGammaTbl->pu16BChannel0[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
            }
            if(u8Channel == 3) //W channel
            {
                if(bSupportWChannel == TRUE)
                {
                    pstGetPNLGammaTbl->pu16WChannel0[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
                }
            }
        }

    }

    if(priv->pnl_lib_version != VERSION4)
    {
        CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16RChannel1);
        CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16GChannel1);
        CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16BChannel1);
        if(bSupportWChannel == TRUE)
        {
            CHECK_PTR_NULL(pstGetPNLGammaTbl->pu16WChannel1);
        }
        // Set Channel1
        // Enable REG_GAMMA_2LUT_EN
        W2BYTEMSK(REG_01A4_PAFRC_BKA324,1,REG_01A4_PAFRC_BKA324_REG_GAMMA_2LUT_EN);
        // Set REG_GAMMA_LUT_SEL 1
        W2BYTEMSK(REG_01A4_PAFRC_BKA324,1,REG_01A4_PAFRC_BKA324_REG_GAMMA_LUT_SEL);
        for(u8Channel = 0; u8Channel <4; u8Channel++)
        {
            //1. set Read channel
            W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,u8Channel,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_CH_SEL_01B4);
            for(u16Addr = 0; u16Addr < u16NumOfLevel; u16Addr++)
            {
                //2. set LUT_ADDR 0
                W2BYTEMSK(REG_01B0_PAFRC_BKA324_V004,u16Addr,REG_01B0_PAFRC_BKA324_V004_REG_GAMMA_ADR_01B0);
                //3. toggle LUT_R_FLAG
                W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,1,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_RD_EN_01B4);
                while(R2BYTEMSK(REG_01B4_PAFRC_BKA324_V004, REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_RD_EN_01B4) && (u16Timeout < MAX_DELAY_TIME))
                {
                    udelay(10);
                    u16Timeout++;
                }

                if(u8Channel == 0) //R channel
                {
                    pstGetPNLGammaTbl->pu16RChannel1[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
                }
                if(u8Channel == 1) //G channel
                {
                    pstGetPNLGammaTbl->pu16GChannel1[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
                }
                if(u8Channel == 2) //B channel
                {
                    pstGetPNLGammaTbl->pu16BChannel1[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
                }
                if(u8Channel == 3) //W channel
                {
                    if(bSupportWChannel == TRUE)
                    {
                        pstGetPNLGammaTbl->pu16WChannel1[u16Addr] = R2BYTEMSK(REG_01C4_PAFRC_BKA324_V004,REG_01C4_PAFRC_BKA324_V004_REG_GAMMA_RD_DATA_01C4);
                    }
                }
            }

        }

        // Disable REG_GAMMA_2LUT_EN
        W2BYTEMSK(REG_01A4_PAFRC_BKA324,0,REG_01A4_PAFRC_BKA324_REG_GAMMA_2LUT_EN);
        // Set REG_GAMMA_LUT_SEL 0
        W2BYTEMSK(REG_01A4_PAFRC_BKA324,0,REG_01A4_PAFRC_BKA324_REG_GAMMA_LUT_SEL);
    }

    if (bGammaByPass == TRUE)
    {
        //restore setting
        MHal_PNL_SetPanelGammaByPass(bGammaByPass);
    }
    return TRUE;
}
static bool MHal_PNL_GetPanelGammaTbl_From_Bin(struct udevice *dev,ST_PNL_PNLGAMMATBL *pstGetPNLGammaTbl)
{
    u32 u32index = 0, u32StartAddress = 0;
    MS_PNL_PNLGAMMA_Config stPNLGammaConfig;
    u8 *u8ptr = NULL;
    bool bSupportWChannel = MHal_PNL_Support_PanelGamma_W_Channel();
    memset(&stPNLGammaConfig,0,sizeof(MS_PNL_PNLGAMMA_Config));
    memcpy(&stPNLGammaConfig,(pstGetPNLGammaTbl->pu8GammaTbl + PANEL_GAMMA_MAINHEADER_LEN),sizeof(MS_PNL_PNLGAMMA_Config));

    u32StartAddress = stPNLGammaConfig.u32Table2DStartAddress + stPNLGammaConfig.u16PreTableAlignedSize * pstGetPNLGammaTbl->u16Index;

    if (pstGetPNLGammaTbl->pu8GammaTbl == NULL)
    {
        return FALSE;
    }

    if (pstGetPNLGammaTbl->pu16RChannel0 == NULL || pstGetPNLGammaTbl->pu16GChannel0 == NULL || pstGetPNLGammaTbl->pu16BChannel0 == NULL)
    {
        return FALSE;
    }

    if(bSupportWChannel == TRUE)
    {
        if( pstGetPNLGammaTbl->pu16WChannel0 == NULL )
        {
            return FALSE;
        }
    }

    if (stPNLGammaConfig.bGamma2LutEnable == TRUE)
    {
        if (pstGetPNLGammaTbl->pu16RChannel1 == NULL || pstGetPNLGammaTbl->pu16GChannel1 == NULL || pstGetPNLGammaTbl->pu16BChannel1 == NULL)
        {
            return FALSE;
        }
        if(bSupportWChannel == TRUE)
        {
            if( pstGetPNLGammaTbl->pu16WChannel1 == NULL )
            {
                return FALSE;
            }
        }
    }

    u8ptr = u32StartAddress + pstGetPNLGammaTbl->pu8GammaTbl;

    if((stPNLGammaConfig.u8GammaType & _BIT(4)))
    {
        pstGetPNLGammaTbl->enGammaType = E_APIPNL_GAMMA_10BIT;
    }
    else if ((stPNLGammaConfig.u8GammaType & _BIT(5)))
    {
        pstGetPNLGammaTbl->enGammaType = E_APIPNL_GAMMA_12BIT;
    }

    if((stPNLGammaConfig.u8GammaType & _BIT(0)))
    {
        pstGetPNLGammaTbl->enGammaEntries = E_PNL_PNLGAMMA_256_ENTRIES;
    }
    else
    {
        pstGetPNLGammaTbl->enGammaEntries = E_PNL_PNLGAMMA_1024_ENTRIES;
    }
    /* data format
    //each cmd:
    //|  d_15  |   d_14  |   d_13  |  d_12   |   d_11  |   d_10  |   d_9   |   d_8   |   d_7   |   d_6  |  d_5  |  d_4  |  d_3  |  d_2  |  d_1  | d_0  |
    //|251:240 | 235:224 | 219:208 | 203:192 | 187:176 | 171:160 | 155:144 | 139:128 | 123:112 | 107:96 | 91:80 | 75:64 | 59:48 | 43:32 | 27:16 | 11:0 |
    //
    //R/G/B/W cmd order in DRAM
    //            |END | START |
    //  R_LUT0     63      0
    //  G_LUT0     127     64
    //  B_LUT0     191     128
    //  W_LUT0     255     192
    //  R_LUT1     319     256
    //  G_LUT1     383     320
    //  B_LUT1     447     384
    //  W_LUT1     511     448
    */

    u8* pu8ptr_R0 = u8ptr;
    u8* pu8ptr_G0 = pu8ptr_R0 + PANEL_GAMMA_CHANNEL_OFFSET;  // 64entry  * 32 byte =  2048
    u8* pu8ptr_B0 = pu8ptr_G0 + PANEL_GAMMA_CHANNEL_OFFSET;
    u8* pu8ptr_W0 = pu8ptr_B0 + PANEL_GAMMA_CHANNEL_OFFSET;

    u8* pu8ptr_R1 = pu8ptr_R0 + PANEL_GAMMA_TBL_OFFSET;
    u8* pu8ptr_G1 = pu8ptr_R1 + PANEL_GAMMA_CHANNEL_OFFSET;
    u8* pu8ptr_B1 = pu8ptr_G1 + PANEL_GAMMA_CHANNEL_OFFSET;
    u8* pu8ptr_W1 = pu8ptr_B1 + PANEL_GAMMA_CHANNEL_OFFSET;

    for(u32index=0 ; u32index<PANEL_GAMMA_ENTRY; u32index++)
    {
        //LUT 0
        pstGetPNLGammaTbl->pu16RChannel0[u32index] = ((u16)*((u16 *)pu8ptr_R0 + u32index));
        pstGetPNLGammaTbl->pu16GChannel0[u32index] = ((u16)*((u16 *)pu8ptr_G0 + u32index));
        pstGetPNLGammaTbl->pu16BChannel0[u32index] = ((u16)*((u16 *)pu8ptr_B0 + u32index));
        if(bSupportWChannel == TRUE)
        {
            pstGetPNLGammaTbl->pu16WChannel0[u32index] = ((u16)*((u16 *)pu8ptr_W0 + u32index));
        }
        if (stPNLGammaConfig.bGamma2LutEnable == TRUE)
        {
            //LUT 1
            pstGetPNLGammaTbl->pu16RChannel1[u32index] = ((u16)*((u16 *)pu8ptr_R1 + u32index));
            pstGetPNLGammaTbl->pu16GChannel1[u32index] = ((u16)*((u16 *)pu8ptr_G1 + u32index));
            pstGetPNLGammaTbl->pu16BChannel1[u32index] = ((u16)*((u16 *)pu8ptr_B1 + u32index));
            if(bSupportWChannel == TRUE)
            {
                pstGetPNLGammaTbl->pu16WChannel1[u32index] = ((u16)*((u16 *)pu8ptr_W1 + u32index));
            }
        }
    }
    return TRUE;
}
static bool _MHal_PNL_ADL_SetPanelGammaTbl(struct udevice *dev,ST_PNL_PNLGAMMATBL *pstSetPNLGammaTbl)
{
#if (defined(UFO_XC_AUTO_DOWNLOAD) && ENABLE_PNL_GAMMA_AUTODOWNLOAD == TRUE)
    u8 *pu8GammaTbl;
    bool bRet = TRUE;
    u32 u32index = 0, u32Size = 0;
    bool b2LutEn = MHal_PNL_PanelGamma_Get2LutEnable(dev);
    u32 u32PnlGammaADLCmdSize;
    u8 *pu8R0 = NULL, *pu8G0 = NULL, *pu8B0 = NULL, *pu8W0 = NULL, *pu8R1 = NULL, *pu8G1 = NULL, *pu8B1 = NULL;
    bool bGammaByPass = MHal_PNL_GetPanelGammaByPass();
    bool bSupportWChannel = MHal_PNL_Support_PanelGamma_W_Channel();

    if( b2LutEn == FALSE )
    {
        if(bSupportWChannel == TRUE)
        {
            u32PnlGammaADLCmdSize = PNLGAMMA_ADL_CMD_256_ENTRY;
        }
        else
        {
            u32PnlGammaADLCmdSize = PNLGAMMA_ADL_CMD_192_ENTRY;
        }
    }
    else
    {
        u32PnlGammaADLCmdSize = PNLGAMMA_ADL_CMD_384_ENTRY;
    }

    u32Size = PNLGAMMA_ADL_CMD_LENGTH*u32PnlGammaADLCmdSize;

    PNL_MALLOC_MEM(pu8GammaTbl, u32Size, bRet);

    if( bRet == TRUE )
    {
        pu8R0 = pu8GammaTbl;
        if( b2LutEn == FALSE )
        {
            pu8G0 = pu8R0 + PANEL_GAMMA_CHANNEL_OFFSET;  // 64entry  * 32 byte =  2048
            pu8B0 = pu8G0 + PANEL_GAMMA_CHANNEL_OFFSET;

            if(bSupportWChannel == TRUE)
            {
                pu8W0 = pu8B0 + PANEL_GAMMA_CHANNEL_OFFSET;
            }
        }
        else
        {
            pu8G0 = pu8R0 + PANEL_GAMMA_CHANNEL_OFFSET;  // 64entry  * 32 byte =  2048
            pu8B0 = pu8G0 + PANEL_GAMMA_CHANNEL_OFFSET;

            pu8R1 = pu8B0 + PANEL_GAMMA_CHANNEL_OFFSET;
            pu8G1 = pu8R1 + PANEL_GAMMA_CHANNEL_OFFSET;
            pu8B1 = pu8G1 + PANEL_GAMMA_CHANNEL_OFFSET;
        }

        for(u32index = 0 ; u32index < PANEL_GAMMA_ENTRY; u32index++)
        {
            if( b2LutEn == FALSE )
            {
                //LUT 0
                *((u16 *)pu8R0 + u32index) = pstSetPNLGammaTbl->pu16RChannel0[u32index];
                *((u16 *)pu8G0 + u32index) = pstSetPNLGammaTbl->pu16GChannel0[u32index];
                *((u16 *)pu8B0 + u32index) = pstSetPNLGammaTbl->pu16BChannel0[u32index];

                if(bSupportWChannel == TRUE)
                {
                    *((u16 *)pu8W0 + u32index) = pstSetPNLGammaTbl->pu16WChannel0[u32index];
                }
            }
            else
            {
                //LUT 0
                *((u16 *)pu8R0 + u32index) = pstSetPNLGammaTbl->pu16RChannel0[u32index];
                *((u16 *)pu8G0 + u32index) = pstSetPNLGammaTbl->pu16GChannel0[u32index];
                *((u16 *)pu8B0 + u32index) = pstSetPNLGammaTbl->pu16BChannel0[u32index];

                //LUT 1
                *((u16 *)pu8R1 + u32index) = pstSetPNLGammaTbl->pu16RChannel1[u32index];
                *((u16 *)pu8G1 + u32index) = pstSetPNLGammaTbl->pu16GChannel1[u32index];
                *((u16 *)pu8B1 + u32index) = pstSetPNLGammaTbl->pu16BChannel1[u32index];
            }
        }

        if (bGammaByPass == TRUE)
        {
            MHal_PNL_SetPanelGammaByPass(FALSE);
        }
        // Write ADL
        if(KHal_XC_WriteAutoDownload(E_PNL_XC_AUTODOWNLOAD_CLIENT_PANEL_GAMMA,pu8GammaTbl,u32Size,NULL)!= TRUE)
        {
            UBOOT_ERROR(" Write ADL fail \n.");
            PNL_FREE_MEM(pu8GammaTbl);
            return FALSE;
        }

        //Fire ADL
        if(KHal_XC_FireAutoDownload(E_PNL_XC_AUTODOWNLOAD_CLIENT_PANEL_GAMMA) != TRUE)
        {
            UBOOT_ERROR(" Fire ADL fail \n.");
            PNL_FREE_MEM(pu8GammaTbl);
            return FALSE;
        }
        PNL_FREE_MEM(pu8GammaTbl);
    }
    else
    {
        return FALSE;
    }
    return TRUE;
#else
    return FALSE;
#endif
}


static bool MHal_PNL_SetPanelGammaTbl(struct udevice *dev, ST_PNL_PNLGAMMATBL *pstSetPNLGammaTbl)
{
    u16 u16NumOfLevel =1024;
    u16 u16Addr = 0;
    u8 u8Channel =0;
    u16 u16Timeout = 0;
    bool bGammaEnable = 0;
    bool bSupportWChannel = MHal_PNL_Support_PanelGamma_W_Channel();
    bool b2LutEn = MHal_PNL_PanelGamma_Get2LutEnable(dev);
    u8 u8MaxChannel = b2LutEn?PANEL_GAMMA_2LUT_MAX_CHANNEL:PANEL_GAMMA_1LUT_MAX_CHANNEL; // 1: RGBRGB, 0: RGBW
    bool bGammaByPass = MHal_PNL_GetPanelGammaByPass();
    struct mtk_panel_priv *priv = dev_get_priv(dev);

    if (priv == NULL) {
        debug("[%s] get device private fail\n", __func__);
        return FALSE;
    }

    if ((priv->pnl_lib_version == VERSION5) || (priv->pnl_lib_version == VERSION6))
    {
        //adl index user mode en have to be set 1 when boot time
        W2BYTEMSK(REG_0080_SCTCON_MISC_BKA3E0_V005, 0x1, REG_0080_SCTCON_MISC_BKA3E0_V005_REG_ADL_IDX_PGA_SEL_0080);
    }

    if( _MHal_PNL_ADL_SetPanelGammaTbl(dev,pstSetPNLGammaTbl) == TRUE )
    {
        //use ADL to set panel gamma table, use ML to set panel gamma enable
        //but ML trigger early ADL so that it shows garbage in AC on
        //so delay 1 vsync for ML
        mdelay(20);
        return TRUE;
    }

    if (bGammaByPass == TRUE)
    {
        MHal_PNL_SetPanelGammaByPass(FALSE);
    }

    // Store Panel Gamma enable flag
    bGammaEnable = MHal_PNL_GetPanelGamma_Enable();
    //Disbale Panel Gamma
    if(bGammaEnable)
    {
        MHal_PNL_PanelGamma_Enable(FALSE);
    }

    //Due to odclk and mcu clock not the same, the set value not stable.
    //Need add 4 NOP for burst wirte to guarantee that set value correct.
    //So use normal write to save time.

    for(u8Channel = 0; u8Channel < u8MaxChannel; u8Channel++)
    {
        W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,0x1,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_BW_EN_01B4); //BW enable
        if( b2LutEn == FALSE )
        {
            // set Write channel
            W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,u8Channel,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_CH_SEL_01B4);
            if(priv->pnl_lib_version != VERSION4)
            {
                //reg_gamma_lut_sel, select lut0 load table
                W2BYTEMSK(REG_01A4_PAFRC_BKA324, 0x0, REG_01A4_PAFRC_BKA324_REG_GAMMA_LUT_SEL);
            }
        }
        else
        {
            // set Write channel
            W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004, (u8Channel%3), REG_01B4_PAFRC_BKA324_REG_GAMMA_CH_SEL);
            if(priv->pnl_lib_version != VERSION4)
            {
                //reg_gamma_lut_sel, select lut0 or lut1 to load table
                W2BYTEMSK(REG_01A4_PAFRC_BKA324, (u8Channel >= 3)?0x1:0x0,REG_01A4_PAFRC_BKA324_REG_GAMMA_LUT_SEL);
            }
        }

        W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,0x1,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_BW_EN_01B4); //BW enable

        for(u16Addr = 0; u16Addr < u16NumOfLevel; u16Addr++)
        {
            //2. set LUT_ADDR
            W2BYTEMSK(REG_01B0_PAFRC_BKA324_V004,u16Addr,REG_01B0_PAFRC_BKA324_V004_REG_GAMMA_ADR_01B0);
            //3. set write data
            if( b2LutEn == FALSE )
            {
                if(u8Channel == 0) //R channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16RChannel0[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                if(u8Channel == 1) //G channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16GChannel0[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                if(u8Channel == 2) //B channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16BChannel0[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                if(u8Channel == 3) //W channel
                {
                    if(bSupportWChannel == TRUE)
                    {
                        W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16WChannel0[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                    }
                }
            }
            else
            {
                //lut0
                if(u8Channel == 0) //R0 channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16RChannel0[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                if(u8Channel == 1) //G0 channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16GChannel0[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                if(u8Channel == 2) //B0 channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16BChannel0[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                //lut1
                if(u8Channel == 3) //R1 channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16RChannel1[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                if(u8Channel == 4) //G1 channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16GChannel1[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
                if(u8Channel == 5) //B1 channel
                {
                    W2BYTEMSK(REG_01B8_PAFRC_BKA324_V004,pstSetPNLGammaTbl->pu16BChannel1[u16Addr],REG_01B8_PAFRC_BKA324_V004_REG_GAMMA_DATA_01B8);
                }
            }

            //4. toggle LUT_W_FLAG_R
            W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,0x1,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_WR_EN_01B4);
            // after setting toggle bit, we need to make sure the bit is already toggled.
            while(R2BYTEMSK(REG_01B4_PAFRC_BKA324_V004, REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_WR_EN_01B4) && (u16Timeout < MAX_DELAY_TIME))
            {
                udelay(10);
                u16Timeout++;
            }
            u16Timeout = 0;
        }

        W2BYTEMSK(REG_01B4_PAFRC_BKA324_V004,0x0,REG_01B4_PAFRC_BKA324_V004_REG_GAMMA_BW_EN_01B4); //Afetr writing one channel, disable BW.
    }

    // restore setting
    if(bGammaEnable)
    {
        MHal_PNL_PanelGamma_Enable(TRUE);
    }
    return TRUE;
}

///drvPNL.c
static bool _MDrv_PNLGammaTbl_MemAllocate(ST_PNL_PNLGAMMATBL *stPNLGammaTbl, bool bGamma2LutEnable)
{
    bool bRet = TRUE;
    bool bReturn = TRUE;
    bool bSupport_PanelGamma_W_Channel = MHal_PNL_Support_PanelGamma_W_Channel();

    if(bGamma2LutEnable == FALSE)
    {
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16RChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16GChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16BChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        if(bSupport_PanelGamma_W_Channel == TRUE)
        {
            PNL_MALLOC_MEM(stPNLGammaTbl->pu16WChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        }

        if(bRet != TRUE)
        {
            debug("[%s][%d] malloc fail\n", __func__,__LINE__);
            bReturn = FALSE;
        }

        if(bSupport_PanelGamma_W_Channel == TRUE)
        {
            if(stPNLGammaTbl->pu16WChannel0 == NULL)
            {
                debug("[%s][%d] malloc fail\n", __func__,__LINE__);
                bReturn = FALSE;
            }
        }
    }
    else
    {
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16RChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16GChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16BChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);

        if(bRet != TRUE)
        {
            debug("[%s][%d] malloc fail\n", __func__,__LINE__);
            bReturn = FALSE;
        }

        PNL_MALLOC_MEM(stPNLGammaTbl->pu16RChannel1, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16GChannel1, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16BChannel1, PANEL_GAMMA_CHANNEL_OFFSET, bRet);

        if(bRet != TRUE)
        {
            debug("[%s][%d] malloc fail\n", __func__,__LINE__);
            bReturn = FALSE;
        }

        PNL_MALLOC_MEM(stPNLGammaTbl->pu16WChannel0, PANEL_GAMMA_CHANNEL_OFFSET, bRet);
        PNL_MALLOC_MEM(stPNLGammaTbl->pu16WChannel1, PANEL_GAMMA_CHANNEL_OFFSET, bRet);

        if(bRet != TRUE)
        {
            debug("[%s][%d] malloc fail\n", __func__,__LINE__);
            bReturn = FALSE;
        }
    }

    if(bReturn == FALSE)
    {
        PNL_FREE_MEM(stPNLGammaTbl->pu16RChannel0);
        PNL_FREE_MEM(stPNLGammaTbl->pu16GChannel0);
        PNL_FREE_MEM(stPNLGammaTbl->pu16BChannel0);
        PNL_FREE_MEM(stPNLGammaTbl->pu16WChannel0);

        PNL_FREE_MEM(stPNLGammaTbl->pu16RChannel1);
        PNL_FREE_MEM(stPNLGammaTbl->pu16GChannel1);
        PNL_FREE_MEM(stPNLGammaTbl->pu16BChannel1);
        PNL_FREE_MEM(stPNLGammaTbl->pu16WChannel1);
        return bReturn;
    }

    return bReturn;
}

//--------------------------------------------------------------------------------------------------------------------
// Panel Gamma Auto Download Format
// Lut0                         2Lut case
// R/G/B/W cmd format in DRAM   R/G/B cmd format in DRAM
//            |END | START |              |END | START |
//  R_LUT0     63      0        R_LUT0     63      0
//  G_LUT0     127     64       G_LUT0     127     64
//  B_LUT0     191     128      B_LUT0     191     128
//  W_LUT0     255     192      R_LUT1     255     192
//                              G_LUT1     319     256
//                              B_LUT1     383     320
// Panel Gamma Bin File Format
// Lut0                         2Lut case
//  R_LUT0     63      0        R_LUT0     63      0
//  G_LUT0     127     64       G_LUT0     127     64
//  B_LUT0     191     128      B_LUT0     191     128
//  W_LUT0     255     192      W_LUT0     255     192
//                              R_LUT1     319     256
//                              G_LUT1     383     320
//                              B_LUT1     447     384
//                              W_LUT1     511     448
//--------------------------------------------------------------------------------------------------------------------
bool MDrv_PNL_SetPanelGammaBIN(struct udevice *dev,u8 * u8GammaTbl, u32 u32Size, u8 u8Index)
{
    ST_PNL_PNLGAMMATBL stPNLGammaTbl;
    MS_PNL_PNLGAMMA_Config stPNLGammaConfig;
    bool bRet = FALSE;

    if(u8GammaTbl == NULL)
    {
        debug("[%s] u8GammaTbl == NULL error\n.", __FUNCTION__);
        return FALSE;
    }

    //get panel gamma sub header
    memset(&stPNLGammaConfig, 0, sizeof(MS_PNL_PNLGAMMA_Config));
    memcpy(&stPNLGammaConfig, (u8GammaTbl + PANEL_GAMMA_MAINHEADER_LEN), sizeof(MS_PNL_PNLGAMMA_Config));

    //get panel gamma RGBW curve table from BIN
    memset(&stPNLGammaTbl, 0, sizeof(ST_PNL_PNLGAMMATBL));
    stPNLGammaTbl.pu8GammaTbl = u8GammaTbl;
    stPNLGammaTbl.enPnlGammaTbl = E_PNL_PNLGAMMA_TBL_FROM_BIN;
    stPNLGammaTbl.u16Index = u8Index;

    if(_MDrv_PNLGammaTbl_MemAllocate(&stPNLGammaTbl, stPNLGammaConfig.bGamma2LutEnable) == FALSE)
    {
        debug("\033[1;32m %s %d: _MDrv_PNLGammaTbl_MemAllocate E_PNL_FAIL\033[0m \n",__func__,__LINE__);
        return FALSE;
    }

    bRet = MHal_PNL_GetPanelGammaTbl_From_Bin(dev,&stPNLGammaTbl);
    if(bRet == TRUE)
    {
        //Set VAC 2Lut mode
        MHal_PNL_PanelGamma_Set2LUTMode(dev, &stPNLGammaConfig);
        MHal_PNL_SetPanelGammaTbl(dev,&stPNLGammaTbl);

        //Enable Panel gamma
        MHal_PNL_PanelGamma_Enable(TRUE);
    }
    else
    {
        debug("[%s] Failed!!!!\n",__FUNCTION__);
    }

    //free memory
    PNL_FREE_MEM(stPNLGammaTbl.pu16RChannel0);
    PNL_FREE_MEM(stPNLGammaTbl.pu16GChannel0);
    PNL_FREE_MEM(stPNLGammaTbl.pu16BChannel0);
    PNL_FREE_MEM(stPNLGammaTbl.pu16WChannel0);

    PNL_FREE_MEM(stPNLGammaTbl.pu16RChannel1);
    PNL_FREE_MEM(stPNLGammaTbl.pu16GChannel1);
    PNL_FREE_MEM(stPNLGammaTbl.pu16BChannel1);
    PNL_FREE_MEM(stPNLGammaTbl.pu16WChannel1);

    return bRet;
}

bool MDrv_PNL_GetPanelGammaTbl(struct udevice *dev,ST_PNL_PNLGAMMATBL *pstGetPNLGammaTbl)
{
    bool bResult = FALSE;
    switch(pstGetPNLGammaTbl->enPnlGammaTbl)
    {
        case E_PNL_PNLGAMMA_TBL_FROM_BIN:
        {
            bResult = MHal_PNL_GetPanelGammaTbl_From_Bin(dev, pstGetPNLGammaTbl);
            break;
        }
        case E_PNL_PNLGAMMA_TBL_FROM_REG:
        {
            bResult = MHal_PNL_GetPanelGammaTbl_From_Reg(dev, pstGetPNLGammaTbl);
            break;
        }
        default:
        {
            debug("ERROR!! SET WRONG type for read Panel gamma!!!!!\n");
            break;
        }

    }
    return bResult;
}

bool MApi_PNL_SetPanelGammaBIN(struct udevice *dev,u8* pu8GammaTab,u32 u32Size, u8 u8Index)
{
    bool bResult = FALSE;

    bResult = MDrv_PNL_SetPanelGammaBIN(dev, pu8GammaTab, u32Size, u8Index);

    return bResult;
}

void MHal_PNL_TCON_Path_Patch(struct udevice *dev)
{
    struct mtk_panel_priv *priv = dev_get_priv(dev);
    if (priv == NULL) {
        debug("[%s] get device private fail\n", __func__);
        return;
    }
    if(priv->tcon_info.stPanelInfo.u32DataPath_sel > E_PNL_TCON_PATH_MODE_0 && priv->tcon_info.stPanelInfo.u32DataPath_sel < E_PNL_TCON_PATH_MODE_MAX)
    {
        u8 u8ModeIdx = priv->tcon_info.stPanelInfo.u32DataPath_sel-1;
        u8 u8RegCount = 0;
		u8 u8PAFRC_SWITCH_TO_MOD_EN = 0;

        for (u8RegCount = 0;u8RegCount < TCON_PATH_REG_COUNT;u8RegCount ++)
        {
            W2BYTEMSK(stTconPathReg[u8RegCount],stTconPathVal[u8RegCount][u8ModeIdx],stTconPathMask[u8RegCount]);
        }
		if(priv->tcon_info.stPanelInfo.u32DataPath_sel == E_PNL_TCON_PATH_MODE_2) // if 144, divided by 1
		{
			//W2BYTEMSK((0x206000+0x198), 0x0, Fld(1,8,AC_MSKB2));
			W2BYTEMSK(REG_0198_CKGEN01_V004, 0x0, REG_0198_CKGEN01_V004_REG_CKG_S_GPO_0198);
		}
		else
		{
			//W2BYTEMSK((0x206000+0x198), 0x1, Fld(1,8,AC_MSKB2));
			W2BYTEMSK(REG_0198_CKGEN01_V004, 0x1, REG_0198_CKGEN01_V004_REG_CKG_S_GPO_0198);
		}
		u8PAFRC_SWITCH_TO_MOD_EN =
			R2BYTEMSK(REG_012C_PAFRC_BKA324_V004,
				  REG_012C_PAFRC_BKA324_V004_REG_PAFRC_SWITCH_TO_MOD_EN_012C);
		//When use PAFRC in MOD, need set OD mode to 1
		if (u8PAFRC_SWITCH_TO_MOD_EN)
			W2BYTEMSK(REG_01E0_TCON_4K, 0x1, REG_01E0_TCON_4K_REG_OD_MODE_01E0);
    }
}

// Dump TCON
void MDrv_PNL_TCON_DumpGENRegTab(struct udevice *dev,u8* pu8TconTab,u16 u16RegisterCount)
{
    u32 u32tabIdx = 0;
    u32 u32Addr;
    u8 u8Mask;
    u8 u8Value;
    //u16 u16TconSubBank;

    debug("MDrv_PNL_TCON_DumpGENRegTab\n");

    debug("tab: gen \n");

    if (pu8TconTab == NULL)
    {
        debug("[%s] TCONTable error \n.", __FUNCTION__);
        return;
    }

    //u16TconSubBank = MHal_PNL_Read_TCON_SubBank(pInstance);
    //PNL_DBG("u16TconSubBank=%x\n", u16TconSubBank);

    while (u16RegisterCount--)
    {
        u32Addr = ((pu8TconTab[u32tabIdx]<<24) + (pu8TconTab[(u32tabIdx +1)]<<16) + (pu8TconTab[(u32tabIdx +2)]<<8) + pu8TconTab[(u32tabIdx +3)]) & 0xFFFFFFFF;
        u8Mask  = pu8TconTab[(u32tabIdx +4)] & 0xFF;
        u8Value = pu8TconTab[(u32tabIdx +5)] & 0xFF;

        debug("[addr=%04tx, msk=%02x, val=%02x] \n", (ptrdiff_t)u32Addr, u8Mask, u8Value);

        //Update to support ext register.
        TCON_W1BYTEMSK(u32Addr, u8Value, u8Mask);
        u32tabIdx = u32tabIdx + 6;
    }

    MHal_PNL_TCON_Path_Patch(dev);
    debug("MDrv_PNL_TCON_DumpGENRegTab end\n");
}

void MDrv_PNL_TCON_DumpGpioRegTab(u8* pu8TconTab,u16 u16RegisterCount)
{
    u32 u32tabIdx = 0;
    u32 u32Addr;
    u8 u8Mask;
    u8 u8Value;
    //u16 u16TconSubBank;

    debug("MDrv_PNL_TCON_DumpGpioRegTab\n");

    if (pu8TconTab == NULL)
    {
        debug("[%s] TCONTable error \n.", __FUNCTION__);
        return;
    }

    //u16TconSubBank = MHal_PNL_Read_TCON_SubBank(pInstance);
    //PNL_DBG("u16TconSubBank=%x\n", u16TconSubBank);

    while (u16RegisterCount--)
    {
        u32Addr = ((pu8TconTab[u32tabIdx]<<24) + (pu8TconTab[(u32tabIdx +1)]<<16) + (pu8TconTab[(u32tabIdx +2)]<<8) + pu8TconTab[(u32tabIdx +3)]) & 0xFFFFFFFF;
        u8Mask  = pu8TconTab[(u32tabIdx +4)] & 0xFF;
        u8Value = pu8TconTab[(u32tabIdx +5)] & 0xFF;

        debug("[addr=%04tx, msk=%02x, val=%02x] \n", (ptrdiff_t)u32Addr, u8Mask, u8Value);

        //Update to support ext register.
        TCON_W1BYTEMSK(u32Addr, u8Value, u8Mask);
        u32tabIdx = u32tabIdx + 6;
    }

    TCON_W1BYTEMSK(0x2444A0, BIT(1), BIT(1));
    mdelay(30); //need to use mdelay , udelay didn't work
    TCON_W1BYTEMSK(0x2444A0, 0, BIT(1));

    debug("MDrv_PNL_TCON_DumpGpioRegTab end\n");
}

